<template>
  <section class="chapter-management">
    <header class="bank-management-heading"><div><h1>客观题库管理</h1><p>管理学生六章练习中的选择题、判断题和填空题。</p></div><el-button type="primary" @click="openNew">新增题目</el-button></header>
    <form class="bank-management-filters" @submit.prevent="apply"><el-select v-model="filters.chapter" placeholder="全部章节" aria-label="筛选章节" @change="apply"><el-option label="全部章节" value=""/><el-option v-for="(title,i) in chapterTitles" :key="i" :label="`${i+1} · ${title}`" :value="i+1"/></el-select><el-select v-model="filters.kind" placeholder="全部题型" aria-label="筛选题型" @change="apply"><el-option label="全部题型" value="objective"/><el-option v-for="(title,kind) in chapterKinds" :key="kind" :label="title" :value="kind"/></el-select><el-input v-model="filters.search" placeholder="搜索题干或命题依据" aria-label="搜索题目" maxlength="150" clearable @clear="apply"/><el-button native-type="submit">查询</el-button></form>
    <el-alert v-if="notice" :title="notice" type="error" :closable="false" role="alert"/>
    <section class="bank-management-table" v-loading="loading"><div class="bank-management-total">共 {{ total }} 道题目</div><p class="mobile-table-note">表格可左右滑动，查看题目与管理操作。</p><el-table :data="items" empty-text="暂无符合条件的题目，可新增或调整筛选。">
      <el-table-column label="章节 / 题型" width="140"><template #default="{row}">第 {{ row.chapter }} 章<small>{{ chapterKinds[row.kind] }}</small></template></el-table-column>
      <el-table-column label="题目" min-width="330"><template #default="{row}"><button class="question-title-link" @click="openEdit(row.id)">{{ row.stem }}</button><small>{{ row.source_reference }}</small></template></el-table-column>
      <el-table-column label="管理" width="150"><template #default="{row}"><div class="question-row-actions"><el-button link type="primary" :disabled="deleting===row.id" @click="openEdit(row.id)">编辑</el-button><el-button link type="danger" :loading="deleting===row.id" :disabled="!!deleting" @click="remove(row)">删除</el-button></div></template></el-table-column>
    </el-table><ListPager :page="page" :total="total" @change="changePage"/></section>
    <el-dialog v-model="editorOpen" :title="editingId?'编辑题目':'新增题目'" width="min(860px, 94vw)" :close-on-click-modal="false" :before-close="closeEditor" destroy-on-close>
      <div v-loading="detailLoading"><el-alert v-if="editorNotice" :title="editorNotice" type="error" :closable="false" role="alert"/>
      <el-form label-position="top" :disabled="saving||detailLoading||loadFailed" @submit.prevent="save">
        <div class="question-form-grid"><el-form-item label="所属章节"><el-select v-model="form.chapter" aria-label="所属章节"><el-option v-for="(title,i) in chapterTitles" :key="i" :label="`${i+1} · ${title}`" :value="i+1"/></el-select></el-form-item><el-form-item label="题型"><el-select v-model="form.kind" aria-label="题型" @change="changeKind"><el-option v-for="(title,kind) in chapterKinds" :key="kind" :label="title" :value="kind"/></el-select></el-form-item></div>
        <el-form-item label="题干（填空题请在题干中标出空位）"><el-input v-model="form.stem" type="textarea" :rows="4" maxlength="10000" show-word-limit aria-label="题干"/></el-form-item>
        <div v-if="images.length" class="question-source-images"><img v-for="image in images" :key="image.src" :src="image.src" :alt="image.alt"/><p>保留原题题图。</p></div>
        <section v-if="['choice','multi'].includes(form.kind)" class="answer-editor"><h2>选项与标准答案</h2><p>勾选正确选项；多选题可勾选多项。</p><div v-for="(_,i) in form.options" :key="i" class="option-editor-row"><label><input v-if="form.kind==='choice'" type="radio" name="correct-choice" v-model="form.answer" :value="optionKey(i)" :disabled="saving||detailLoading" :aria-label="`选项${optionKey(i)}为标准答案`"/><input v-else type="checkbox" v-model="form.answer" :value="optionKey(i)" :disabled="saving||detailLoading" :aria-label="`选项${optionKey(i)}为标准答案`"/>{{ optionKey(i) }}</label><el-input v-model="form.options[i]" :aria-label="`选项${optionKey(i)}`" maxlength="3000"/><el-button :disabled="form.options.length<=2" @click="removeChapterOption(form,i)" :aria-label="`删除选项${optionKey(i)}`">移除</el-button></div><el-button :disabled="form.options.length>=12" @click="form.options.push('')">增加选项</el-button></section>
        <el-form-item v-else-if="form.kind==='true_false'" label="标准答案"><el-radio-group v-model="form.answer" aria-label="判断题标准答案"><el-radio :value="true">正确</el-radio><el-radio :value="false">错误</el-radio></el-radio-group></el-form-item>
        <section v-else class="answer-editor"><h2>逐空填写标准答案</h2><div v-for="(blank,i) in blanks" :key="i" class="blank-editor"><div><strong>第 {{ i+1 }} 空</strong><el-button :disabled="blanks.length<=1" @click="blanks.splice(i,1)">移除此空</el-button></div><el-form-item label="标准答案"><el-input v-model="blank.answer" :aria-label="`第${i+1}空标准答案`" maxlength="1000"/></el-form-item><el-form-item label="其他可接受写法（可选，每行一种）"><el-input v-model="blank.variants" type="textarea" :rows="2" :aria-label="`第${i+1}空其他写法`" maxlength="30000"/></el-form-item></div><el-button :disabled="blanks.length>=20" @click="blanks.push({answer:'',variants:''})">增加一空</el-button></section>
        <el-form-item label="答案解析（可选）"><el-input v-model="form.explanation" type="textarea" :rows="3" maxlength="10000" aria-label="答案解析"/></el-form-item>
        <el-form-item label="命题与答案依据"><el-input v-model="form.source_reference" maxlength="1500" placeholder="填写教材位置、实验资料，或注明教师自编" aria-label="命题与答案依据"/></el-form-item>
        <p class="question-save-note">保存后按教师填写的答案判分；已有作答继续使用提交时的题目与答案。</p>
        <div class="question-editor-actions"><el-button @click="closeEditor()">取消</el-button><el-button type="primary" native-type="submit" :loading="saving">保存题目</el-button></div>
      </el-form></div>
    </el-dialog>
  </section>
</template>
<script setup>
import { onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import ListPager from '@/components/ListPager.vue'
import { listChapterQuestions, getChapterQuestion, createChapterQuestion, editChapterQuestion, deleteChapterQuestion } from '@/api/chapterAuthoring'
import { chapterTitles, chapterKinds, optionKey, emptyChapterQuestion, chapterPayload, removeChapterOption } from '@/domain/chapterAuthoring'
const filters=reactive({chapter:'',kind:'objective',search:''}),page=ref(1),items=ref([]),total=ref(0),loading=ref(false),notice=ref(''),deleting=ref('')
const editorOpen=ref(false),loadFailed=ref(false),detailLoading=ref(false),saving=ref(false),editorNotice=ref(''),editingId=ref(''),revision=ref(0),form=reactive(emptyChapterQuestion()),blanks=ref([{answer:'',variants:''}]),images=ref([])
let serial=0,detailSerial=0,baseline=''
const errorText=e=>typeof e.response?.data?.detail==='string'?e.response.data.detail:e.message||'操作失败，请重试'
const draft=()=>JSON.stringify({form,blanks:blanks.value})
async function load(){const ticket=++serial;loading.value=true;notice.value='';try{const data=await listChapterQuestions({...filters,chapter:filters.chapter||undefined,page:page.value,limit:6});if(ticket!==serial)return;items.value=data.items;total.value=data.total;if(!items.value.length&&page.value>1){page.value=Math.max(1,Math.ceil(total.value/6));await load()}}catch(e){if(ticket===serial)notice.value=errorText(e)}finally{if(ticket===serial)loading.value=false}}
function apply(){page.value=1;load()}
function changePage(value){page.value=value;load()}
function reset(){loadFailed.value=false;Object.assign(form,emptyChapterQuestion());blanks.value=[{answer:'',variants:''}];images.value=[];editorNotice.value='';revision.value=0}
function openNew(){if(saving.value)return;detailSerial++;detailLoading.value=false;reset();editingId.value='';baseline=draft();editorOpen.value=true}
async function openEdit(id){const ticket=++detailSerial;reset();editingId.value=id;detailLoading.value=true;editorOpen.value=true;baseline=draft();try{const data=await getChapterQuestion(id);if(ticket!==detailSerial)return;Object.assign(form,{chapter:data.chapter,kind:data.kind,stem:data.stem,options:data.options.map(o=>o.text),answer:data.answer,accepted:[],explanation:data.explanation,source_reference:data.source_reference});if(form.kind==='multi'&&!Array.isArray(form.answer))form.answer=[];if(form.kind==='cell'){const answers=Array.isArray(data.answer)?data.answer:[data.answer||''];blanks.value=answers.map((answer,i)=>({answer,variants:(data.accepted[i]||[]).filter(v=>v!==answer).join('\n')}))}images.value=data.images||[];revision.value=data.revision;baseline=draft()}catch(e){if(ticket===detailSerial){loadFailed.value=true;editorNotice.value=errorText(e)}}finally{if(ticket===detailSerial)detailLoading.value=false}}
function changeKind(){form.answer=form.kind==='multi'?[]:null;if(form.options.length<2)form.options=['','','',''];blanks.value=[{answer:'',variants:''}]}
async function closeEditor(done){if(saving.value)return;if(!detailLoading.value&&draft()!==baseline){try{await ElMessageBox.confirm('题目有未保存修改，确认放弃？','关闭编辑',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'})}catch{return}}detailSerial++;detailLoading.value=false;editorOpen.value=false;if(typeof done==='function')done()}
async function save(){if(saving.value||detailLoading.value||loadFailed.value)return;editorNotice.value='';let body;try{body=chapterPayload(form,blanks.value)}catch(e){editorNotice.value=e.message;return}saving.value=true;try{if(editingId.value)await editChapterQuestion(editingId.value,{...body,revision:revision.value});else await createChapterQuestion(body);baseline=draft();editorOpen.value=false;ElMessage.success('题目已保存');await load()}catch(e){editorNotice.value=errorText(e)}finally{saving.value=false}}
async function remove(row){if(deleting.value)return;try{await ElMessageBox.confirm('删除后学生将无法再浏览或抽取此题，已有作答记录保留。确认删除？','删除题目',{confirmButtonText:'删除题目',cancelButtonText:'取消',type:'warning'})}catch{return}deleting.value=row.id;try{await deleteChapterQuestion(row.id,row.revision);ElMessage.success('题目已删除');await load()}catch(e){notice.value=errorText(e)}finally{deleting.value=''}}
onBeforeRouteLeave(async()=>{if(!editorOpen.value)return true;await closeEditor();return !editorOpen.value})
function unload(event){if(editorOpen.value&&draft()!==baseline){event.preventDefault();event.returnValue=''}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload)});onBeforeUnmount(()=>{serial++;detailSerial++;window.removeEventListener('beforeunload',unload)})
</script>
<style scoped>
.mobile-table-note{display:none}@media(max-width:650px){.mobile-table-note{display:block;color:#586f82;font-size:13px;margin:0 0 12px}}
.bank-management-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:25px;border-top:3px solid #c6aa70;padding-top:20px}.bank-management-heading h1{margin:0 0 8px;font-size:27px}.bank-management-heading p,.question-save-note{margin:0;color:#586f82;font-size:14px;line-height:1.8}.bank-management-filters{display:flex;gap:12px;margin-bottom:20px}.bank-management-filters>.el-select{width:230px}.bank-management-filters>.el-input{flex:1;min-width:0}.bank-management-table{background:white;border:1px solid #e0e7ef;border-radius:9px;padding:20px}.bank-management-total{font-size:14px;color:#586f82;margin-bottom:14px}.bank-management-table small{display:block;color:#708094;font-size:13px;margin-top:5px}.question-title-link{border:0;background:none;padding:0;color:#19334d;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;font-weight:600}.question-title-link:hover{color:#0075b7}.question-row-actions{display:flex;gap:12px}.question-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.question-form-grid .el-select{width:100%}.answer-editor{border-top:1px solid #e0e7ef;padding:18px 0;margin-bottom:20px}.answer-editor h2{font-size:18px;margin:0 0 10px}.answer-editor>p{color:#586f82;font-size:14px}.option-editor-row{display:flex;align-items:center;gap:12px;margin-bottom:12px}.option-editor-row>label{display:flex;align-items:center;gap:8px;flex-shrink:0}.option-editor-row>.el-input{flex:1;min-width:0}.blank-editor{border:1px solid #e0e7ef;padding:16px;border-radius:6px;margin:14px 0}.blank-editor>div:first-child{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.question-editor-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:22px}.question-source-images img{max-width:100%;max-height:280px;object-fit:contain}.question-source-images p{font-size:13px;color:#586f82}@media(max-width:650px){.bank-management-heading{align-items:flex-start}.bank-management-heading h1{font-size:23px}.bank-management-filters{flex-wrap:wrap}.bank-management-filters>.el-select{width:100%}.bank-management-filters>.el-input{flex-basis:65%}.bank-management-table{padding:12px}.question-form-grid{grid-template-columns:minmax(0,1fr);gap:0}.option-editor-row{gap:7px}.option-editor-row .el-button{padding:8px}.question-editor-actions .el-button{flex:1}}
</style>
